			Console.WriteLine("Frame-pointer candidate: " + candidate);
		}

		foreach (SequenceNumber seq in results.getReturnAddresses()) {
			int index = 0;
			Iterator<ContextState> contextStates = results.getContextStates(seq);
			while (contextStates.hasNext()) {
